// Builds dist/data/stratagem-attacks.js: the damage of stratagem attacks that the demolition page
// needs to wear a structure's health down, read from the wiki attack datamine
// (db/source/stratagems_data.json, weapons_data.json). Do not edit the output.
// Only record names are listed here; every number comes from the datamine. Left out on purpose:
// beams and sprays (continuous damage, not per shot), cluster bomblets and other attacks whose hit
// count is an assumption, and stratagems the datamine has no attack for (HMG and Anti-Tank
// Emplacement, Tesla Tower, Hellbombs).
// Usage: node scripts/build-stratagem-attacks.mjs
import { readFile, writeFile } from 'node:fs/promises';

// stratagem id -> demolition mode id -> [direct record or null, explosion record or null]
export const ATTACKS = {
  'orbital-gatling': { standard: ['S_P16', 'S_P16_IE'] },
  'orbital-napalm': { standard: ['S_P20', 'S_P20_IE'] },
  'orbital-railcannon': { standard: ['S_P26', 'S_P26_E'] },
  'eagle-airstrike': { standard: ['S_P2', 'S_P2_IE'] },
  'eagle-strafing': { standard: ['P5', 'P5_IE'] },
  'eagle-napalm': { standard: ['S_P3', 'S_P3_IE'] },
  'eagle-rockets': { standard: ['S_P1', 'S_P1_IE'] },
  'grenadier-battlement': { standard: ['GL-21_P', 'GL-21_P_IE'] },
  'autocannon-sentry': { standard: ['A/AC-8_P', 'A/AC-8_P_IE'] },
  'rocket-sentry': { standard: ['A/MLS-4X_P', 'A/MLS-4X_P_IE'] },
  'mortar-sentry': { standard: ['A/M-12_P', 'A/M-12_P_IE'] },
  'ems-mortar': { standard: ['A/M-23_P', 'A/M-23_P_IE'] },
  'at-mines': { standard: [null, 'ANTI-TANK MINES_E'] },
  'personnel-mines': { standard: [null, 'ANTI-PERSONNEL MINEFIELD_E'] },
  'incendiary-mines': { standard: [null, 'INCENDIARY MINES_E'] },
  // Vehicles, one demolition mode per weapon tab (the tab's datamine record in data-equipment.js); the
  // Lumberer's flamethrower is a spray and left out.
  'maelstrom': { missile: [null, 'SWP_MAELSTROMIII_E'], gatling: ['P11', null] },
  'patriot': { rocket: ['P6', 'P6_IE'], mg: ['MG-43_P', null] },
  'lumberer': { cannon: ['P8', 'P8_IE'] },
  'bastion': { main: ['P10', 'P10_IE'], coax: ['MG-206_P', null] },
  // SEAF shells: matched by the explosion's demolition force and radius to the stratagem's modes.
  'seaf-artillery': {
    he: ['S_P8', 'S_P8_IE'], 'high-yield': ['S_P9', 'S_P9_IE'], 'mini-nuke': ['S_P10', 'S_P10_IE'],
    napalm: ['S_P11', 'S_P11_IE'], ems: ['S_P7', 'S_P7_IE'], smoke: ['S_P12', null],
  },
};

const read = async name => JSON.parse(await readFile(new URL(`../db/source/${name}`, import.meta.url), 'utf8'));

export async function buildStratagemAttacks() {
  const stratFile = await read('stratagems_data.json');
  const weaponsFile = await read('weapons_data.json');
  const sets = [stratFile.data, weaponsFile.data];
  const find = (type, name) => sets.map(data => data[type]?.[name]).find(Boolean);
  const damageOf = (name, type) => {
    const record = find(type, name);
    if (!record) throw new Error(`${name}: no ${type} record in the datamine`);
    // A smoke shell's explosion has no damage record: it does no damage.
    const hit = record.damage_id ? find('damage', record.damage_id) : null;
    return hit ? { standard: hit.dmg, durable: hit.dmg2, ap: hit.ap1 } : { standard: 0, durable: 0, ap: 0 };
  };
  const damage = {};
  for (const [id, modes] of Object.entries(ATTACKS)) {
    damage[id] = {};
    for (const [mode, [direct, blast]] of Object.entries(modes)) {
      const d = direct ? damageOf(direct, 'projectile') : { standard: 0, durable: 0, ap: 0 };
      const e = blast ? damageOf(blast, 'explosion') : { standard: 0, durable: 0, ap: 0 };
      damage[id][mode] = {
        standard: d.standard, durable: d.durable, ap: d.ap, explosion: e.standard, explosionAp: e.ap,
        ...(e.durable !== e.standard && { explosionDurable: e.durable }),
      };
    }
  }
  return { source: { stratagems: stratFile.revision, weapons: weaponsFile.revision }, damage };
}

if (import.meta.url === `file:///${process.argv[1].replaceAll('\\', '/').replace(/^\//, '')}`) {
  const data = await buildStratagemAttacks();
  const lines = Object.entries(data.damage).map(([id, modes]) => `  ${JSON.stringify(id)}: ${JSON.stringify(modes)},`);
  await writeFile(new URL('../dist/data/stratagem-attacks.js', import.meta.url), `// Generated by scripts/build-stratagem-attacks.mjs from the Helldivers Wiki attack datamine (CC BY-NC-SA 4.0). Do not edit.
// Damage per shot of stratagem attacks for the demolition health path: direct hit (standard, durable,
// AP) and explosion (damage, AP), by stratagem and demolition mode.
export const stratagemAttackSource = ${JSON.stringify(data.source)};
export const stratagemAttackDamage = {
${lines.join('\n')}
};
`);
  console.log(`${lines.length} stratagems`);
}
